# Tools

You may call one or more functions to assist with the user query.

You are provided with function signatures within <tools></tools> XML tags:
<tools>[
    {
        "name": "calculate_vehicle_emissions",
        "description": "Calculate the carbon emissions for a given vehicle type over a specified driving range.",
        "parameters": {
            "vehicle_type": {
                "type": "string",
                "description": "The type of vehicle (e.g., electric, gasoline)."
            },
            "driving_range": {
                "type": "number",
                "description": "The driving range in miles."
            },
            "emission_factor": {
                "type": "number",
                "description": "The emission factor in grams CO2 per mile for the vehicle type."
            }
        },
        "required": [
            "vehicle_type",
            "driving_range",
            "emission_factor"
        ]
    },
    {
        "name": "get_battery_lifecycle_emissions",
        "description": "Retrieve or calculate the average lifecycle carbon footprint of an electric vehicle battery.",
        "parameters": {
            "battery_type": {
                "type": "string",
                "description": "The type of battery used in the electric vehicle."
            },
            "production_emission_factor": {
                "type": "number",
                "description": "The emission factor for battery production in grams CO2 per kWh."
            },
            "battery_capacity": {
                "type": "number",
                "description": "The battery capacity in kWh."
            }
        },
        "required": [
            "battery_type",
            "production_emission_factor",
            "battery_capacity"
        ]
    }
]</tools>

